import { describe, expect, test } from "bun:test";
import * as THREE from "three";
import { CUSTOM_NAME_MAX_LEN, ENCHANT_MAX_LEVEL, INVENTORY_SLOTS } from "@/lib/game/config";
import { MAX_HEARTS, MAX_HUNGER } from "@/lib/game/config";
import {
  inventorySlotsSnapshot,
  migrateSaveV1toV2,
  migrateSaveV2toV3,
  migrateSaveV3toV4,
  migrateSaveV4toV5,
  migrateSaveV5toV6,
  migrateSaveV6toV7,
  migrateSaveV7toV8,
  migrateSaveV8toV9,
  migrateSaveV9toV10,
  migrateSaveV10toV11,
  migrateSaveV11toV12,
  migrateSaveV12toV13,
  migrateSaveV13toV14,
  migrateSaveV14toV15,
  migrateSaveV15toV16,
  migrateSaveV16toV17,
  isPersistentMob,
  readContainers,
  readLootedChests,
  readSave,
  restoreMobs,
  serializeMobs,
  restoreDayClock,
  restoreEquippedArmor,
  restoreDifficulty,
  restoreEffects,
  restoreGameMode,
  restoreGameOver,
  restoreHardcore,
  restoreHearts,
  restoreHungerLevel,
  restoreInventorySlots,
  restorePlayerPosition,
  restoreAdvancements,
  restoreSpawnPoint,
  restoreStats,
  restoreVehicles,
  restoreXp,
  serializeContainers,
  serializeEffects,
  serializeLootedChests,
  serializeStats,
  serializeVehicles,
  writeSave
} from "@/lib/game/save";
import { createSlot, createEmptySlot } from "@/lib/game/items";
import type {
  InventorySlot,
  SaveData,
  SaveDataV1,
  SaveDataV2,
  SaveDataV3,
  SaveDataV4,
  SaveDataV5,
  SaveDataV6,
  SaveDataV7,
  SaveDataV8,
  SaveDataV9,
  SaveDataV10,
  SaveDataV11,
  SaveDataV12,
  SaveDataV13,
  SaveDataV14,
  SaveDataV15,
  SaveDataV16,
  SavedMob,
  SavedPlayer
} from "@/lib/game/types";
import type { MobState } from "@/lib/game/engine/state";

function memoryStorage(initial: Record<string, string> = {}): Storage {
  const data = new Map(Object.entries(initial));
  return {
    get length() {
      return data.size;
    },
    clear: () => data.clear(),
    getItem: (key: string) => data.get(key) ?? null,
    key: (index: number) => [...data.keys()][index] ?? null,
    removeItem: (key: string) => void data.delete(key),
    setItem: (key: string, value: string) => void data.set(key, value)
  };
}

const KEY = "test_save";

/** The flat pre-v17 shape — kept flat so round-trips exercise the v16→v17 players migration. */
function sampleSaveV16(): SaveDataV16 {
  return {
    version: 16,
    gameMode: "creative",
    difficulty: "hard",
    seed: 1337,
    changes: [
      [42, 0],
      [99, 3]
    ],
    inventorySlots: [
      { id: "dirt", count: 12 },
      { id: "wood_pickaxe", count: 1, durability: 35 },
      { id: null, count: 0 }
    ],
    equippedArmor: { helmet: { id: "helmet", count: 1 } },
    selectedSlot: 2,
    player: { x: 100.5, y: 48, z: 200.25 },
    dayClock: 123.5,
    hearts: 14,
    hunger: 9,
    spawnPoint: { x: 10, y: 40, z: 20 },
    lootedChests: [100, 200],
    stats: [
      { id: "blocks_mined", value: 42 },
      { id: "play_time", value: 123.5 }
    ],
    advancements: ["getting_wood", "stone_age"]
  };
}

/** The v17 player entry equivalent to sampleSaveV16's flat per-player fields. */
function samplePlayer(): SavedPlayer {
  return {
    id: "local",
    position: { x: 100.5, y: 48, z: 200.25 },
    inventorySlots: [
      { id: "dirt", count: 12 },
      { id: "wood_pickaxe", count: 1, durability: 35 },
      { id: null, count: 0 }
    ],
    equippedArmor: { helmet: { id: "helmet", count: 1 } },
    selectedSlot: 2,
    gameMode: "creative",
    hearts: 14,
    hunger: 9,
    spawnPoint: { x: 10, y: 40, z: 20 },
    stats: [
      { id: "blocks_mined", value: 42 },
      { id: "play_time", value: 123.5 }
    ],
    advancements: ["getting_wood", "stone_age"]
  };
}

/** The current (v17) shape — exactly what sampleSaveV16 migrates to. */
function sampleSave(): SaveData {
  return {
    version: 17,
    difficulty: "hard",
    seed: 1337,
    changes: [
      [42, 0],
      [99, 3]
    ],
    dayClock: 123.5,
    lootedChests: [100, 200],
    players: [samplePlayer()]
  };
}

/** Persists a flat pre-v17 save so a subsequent readSave has to run the players migration. */
function writeSaveV16(storage: Storage, save: SaveDataV16): void {
  writeSave(KEY, save as unknown as SaveData, storage);
}

describe("save round-trip", () => {
  test("writeSave then readSave preserves every field", () => {
    const storage = memoryStorage();
    writeSave(KEY, sampleSave(), storage);
    expect(readSave(KEY, storage)).toEqual(sampleSave());
  });

  test("a stored flat v16 save reads back as the migrated v17 shape", () => {
    const storage = memoryStorage();
    writeSaveV16(storage, sampleSaveV16());
    expect(readSave(KEY, storage)).toEqual(sampleSave());
  });

  test("legacy saves with inventoryCounts instead of inventorySlots still parse", () => {
    const legacy = {
      version: 1,
      seed: 7,
      changes: [],
      inventoryCounts: { dirt: 30, stone: 5 },
      selectedSlot: 0,
      player: { x: 1, y: 2, z: 3 }
    };
    const storage = memoryStorage({ [KEY]: JSON.stringify(legacy) });
    const parsed = readSave(KEY, storage);
    expect(parsed).not.toBeNull();
    expect(parsed!.version).toBe(17);
    expect(parsed!.inventoryCounts).toEqual({ dirt: 30, stone: 5 });
    expect(parsed!.players[0].inventorySlots).toBeUndefined();
  });
});

